// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 deposit, uint256 warp) public {
        vm.assume(deposit <= VALUE_CAP);
        address actor = address(0xA11CE);

        // Admissible domain: MinSum is fixed at 1 ether.
        uint256 minSum = c.MinSum();

        // Keep the deposit non-trivial but bounded, and the requested amount bounded by the deposit.
        deposit = bound(deposit, 0, 100 ether);
        amount = bound(amount, 0, deposit);

        // Set a starting timestamp so unlockTime can be before/after it.
        warp = bound(warp, 0, 10_000_000);
        vm.warp(warp);

        // Deposit using Put. Put itself normalizes unlockTime to max(_unlockTime, block.timestamp).
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(unlockTime);

        (uint256 storedUnlockTime, uint256 preBalance) = c.Acc(actor);

        // Snapshot only what is observable before Collect.
        uint256 preContractBalance = address(c).balance;

        // Prepare the caller as the same actor and execute Collect.
        vm.deal(actor, 0);
        vm.prank(actor);
        try c.Collect{value: 0}(amount) {
            (uint256 postUnlockTime, uint256 postBalance) = c.Acc(actor);
            uint256 postContractBalance = address(c).balance;

            bool debited = postBalance < preBalance;
            if (debited) {
                // If the reference actually debited, then its guard must have held:
                // balance before >= MinSum, amount <= balance before, and timestamp > unlockTime.
                assertTrue(
                    preBalance >= minSum &&
                    amount <= preBalance &&
                    preContractBalance >= amount &&
                    block.timestamp > storedUnlockTime
                );
            }
        } catch {
            // Reverting Collect is allowed for the reference; no assertion needed here.
        }
    }
}
